-- Generated by model/lib/sql/generate.mjs. Loads IMPORT OPEX from cells/IMPORT OPEX.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT OPEX.csv
INSERT INTO "IMPORT OPEX" SELECT coalesce(k0."Cost Center", fpabench_error('cells name a member Cost Center does not have: ' || c."Cost Center")), coalesce(k1."Account", fpabench_error('cells name a member Account does not have: ' || c."Account")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4
ON CONFLICT ("Cost Center", "Account", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT OPEX";
